import{_ as o,o as t,c as i,aO as p}from"./chunks/framework.BFrk9dwu.js";const l="/blog/1598336593529.png",r="/blog/1598336703507.png",e="/blog/1598336844516.png",n="/blog/1598336878909.png",s="/blog/1598337831371.png",c="/blog/1598338686622.png",d="/blog/1598338777659.png",_="/blog/1598426247591.png",g="/blog/1598339875488.png",m="/blog/1598340007042.png",u="/blog/1598340185697.png",b="/blog/1598426671789.png",h="/blog/1598426793512.png",A="/blog/1598426959647.png",j="/blog/1598427446064.png",q="/blog/1598427674264.png",v="/blog/1598427749672.png",k="/blog/1598427941169.png",f="/blog/1598428024826.png",P="/blog/1598428235095.png",x="/blog/1598428267106.png",O=JSON.parse('{"title":"ReactNative环境搭建","description":"","frontmatter":{"date":"2026-11-18T15:04:14.000Z","title":"ReactNative环境搭建","permalink":"/pages/b1501f","coverImg":"/cover/rn.png","categories":["博客"]},"headers":[],"relativePath":"博客/ReactNative环境搭建.md","filePath":"博客/ReactNative环境搭建.md"}'),S={name:"博客/ReactNative环境搭建.md"};function J(N,a,H,R,T,V){return t(),i("div",null,[...a[0]||(a[0]=[p('<h1 id="reactnative环境搭建" tabindex="-1">ReactNative环境搭建 <a class="header-anchor" href="#reactnative环境搭建" aria-label="Permalink to &quot;ReactNative环境搭建&quot;">​</a></h1><h2 id="安装java-jdk" tabindex="-1">安装java JDK <a class="header-anchor" href="#安装java-jdk" aria-label="Permalink to &quot;安装java JDK&quot;">​</a></h2><ul><li>修改环境变量，新增JAVA_HOME的系统环境变量，值为安装的JDK目录</li></ul><p><img src="'+l+'" alt="1598336593529"></p><ul><li><p>修改系统环境变量PATH，新增两个bin</p><p><img src="'+r+'" alt="1598336703507"></p></li><li><p>新建环境系统变量CLASSPATH，值为JDK文件夹中lib中dt.jar和tool.jar</p><blockquote><p>这个新建变量的时候选值不好选，不应该浏览目录，而是需要浏览文件</p><p>这里需要添加两个文件，所以可以找到第二个文件的目录，用分号粘贴在第一个后面即可</p></blockquote></li></ul><p><img src="'+e+'" alt="1598336844516"></p><p><img src="'+n+'" alt="1598336878909"></p><blockquote><p>最后运行cmd命令窗口，输入javac,如果出现javac的命令选项，则配置成功</p></blockquote><h2 id="安装node-js环境" tabindex="-1">安装node.js环境 <a class="header-anchor" href="#安装node-js环境" aria-label="Permalink to &quot;安装node.js环境&quot;">​</a></h2><p>这个在开发的时候就已经装好了，可以省略</p><h2 id="安装c-环境" tabindex="-1">安装C++环境 <a class="header-anchor" href="#安装c-环境" aria-label="Permalink to &quot;安装C++环境&quot;">​</a></h2><p>大多数操作系统自带C++环境，不需要额外操作</p><h2 id="安装git环境" tabindex="-1">安装git环境 <a class="header-anchor" href="#安装git环境" aria-label="Permalink to &quot;安装git环境&quot;">​</a></h2><p>省略</p><h2 id="安装python环境" tabindex="-1">安装python环境 <a class="header-anchor" href="#安装python环境" aria-label="Permalink to &quot;安装python环境&quot;">​</a></h2><p>注意：要装2.x版本的</p><p>在安装的时候要把最后一个选项购选，那是安装完会添加系统环境变量，如果没勾选，需自己手动添加</p><p><img src="'+s+'" alt="1598337831371"></p><h2 id="配置android环境" tabindex="-1">配置android环境 <a class="header-anchor" href="#配置android环境" aria-label="Permalink to &quot;配置android环境&quot;">​</a></h2><ul><li>安装软件</li><li>把android-23.rar，android-24.rar，android-25.rar这三个文件移动到android安装目录下的platforms这个文件夹中，解压缩（解压到当前文件夹）</li></ul><p><img src="'+c+'" alt="1598338686622"></p><ul><li>把platform-tools_r23.1.0-windows.zip这个文件夹解压缩后，把解压缩的文件夹放到Android根目录中</li></ul><p><img src="'+d+'" alt="1598338777659"></p><ul><li><p>在安装根目录下新建build-tools文件夹，然后把<code>build-tools_r23.0.1-windows.zip</code>,<code>build-tools_r23.0.2-windows.zip</code>,<code>build-tools_r23.0.3-windows.zip</code>这几个文件移到新建的文件夹中，由于解压后的名字都是重复的，所以需要一个一个解压，并重命名，名字就用当前的版本号即可</p><p>这个是用来打包的</p></li></ul><p><img src="'+_+'" alt="1598426247591"></p><ul><li>在安装根目录中新建extras文件夹，在这个文件夹下在新建android文件夹，然后把<code>android_m2repository_r40.zip</code>,<code>support_r23.2.1.zip</code>这几个文件移到android文件夹下解压缩</li></ul><p><img src="'+g+'" alt="1598339875488"></p><ul><li>新建系统环境变量</li></ul><p><img src="'+m+'" alt="1598340007042"></p><ul><li>在系统环境变量path中添加两个文件</li></ul><p><img src="'+u+'" alt="1598340185697"></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>前面的环境配置按照步骤没有什么问题，主要是安卓环境配置</p><p>上面配置安卓的文件都是准备好的，但是由于RN的更新，就导致需要使用对应的包，这样可以自己下载</p><ul><li>先安装Android SDK Tools，安装成功后可以直接打开，也可以在安装目录中打开</li></ul><p><img src="'+b+'" alt="1598426671789"></p><ul><li>打开这个软件的时候如果没有按照上面的操作去执行的话，里面是空的</li></ul><p><img src="'+h+'" alt="1598426793512"></p><ul><li><p><img src="'+A+'" alt="1598426959647"></p><blockquote><p>第一个包是必须要安装的</p><p>第二个是用来打包使用的，也是必须要安装的，不过有许多版本要安装对应的版本。我使用的RN是最新版的0.63，所以配对使用的打包工具是28.0.3，如果不知道需要下载什么版本，在运行打包编译的时候，会出现报错，会出现Android SDK Build-tools这种关键字眼，后面有需要下载的版本</p></blockquote></li><li><p><img src="'+j+'" alt="1598427446064"></p></li></ul><p>这些工具是针对不同手机安卓版本，现在安卓版本怎么也得到10了吧，可以多下几个版本</p><p><img src="'+q+'" alt="1598427674264"></p><ul><li><p>最后还需要下一些扩展</p><p><img src="'+v+'" alt="1598427749672"></p></li></ul><p>以上就是运行安卓所需要的SDK，下载完成就需要配置本地环境变量</p><p><img src="'+k+'" alt="1598427941169"></p><p>然后在系统环境变量path中继续添加</p><p><img src="'+f+'" alt="1598428024826"></p><p>最后需要注意的是要打开手机的权限</p><p>首先找到手机开发者选项</p><p><img src="'+P+'" alt="1598428235095"></p><p><img src="'+x+'" alt="1598428267106"></p><p>要打开USB调试，同时允许USB安装，因为在运行的时候会向手机中安装你当前项目的apk</p><h2 id="java升级16" tabindex="-1">java升级16 <a class="header-anchor" href="#java升级16" aria-label="Permalink to &quot;java升级16&quot;">​</a></h2><p>升级后不会中途弹出安装jre</p><p>安装最新的后需要配置三个环境变量</p><p>系统变量</p><p><strong>新建第一个系统变量</strong> 名：JAVA_HOME 值：jdk安装的目录</p><p><strong>新建第二个系统变量</strong> 名： CLASSPATH 值： .;%JAVA_HOME%\\lib\\dt.jar;%JAVA_HOME%\\lib\\tools.jar</p><p><strong>第三个变量</strong><strong>打开Path</strong>，点击新建按钮，添加变量值：%JAVA_HOME%\\bin;%JAVA_HOME%\\jre\\bin（注意：从分号分开作为两行）。 Path %JAVA_HOME%\\bin %JAVA_HOME%\\jre\\bin</p>',58)])])}const D=o(S,[["render",J]]);export{O as __pageData,D as default};
